def split_row(line: str):
    """Split one CSV line into fields, respecting quoted commas and quotes."""
    fields = []
    field = []
    in_quotes = False
    index = 0

    while index < len(line):
        character = line[index]

        if in_quotes:
            if character == '"':
                if index + 1 < len(line) and line[index + 1] == '"':
                    field.append('"')
                    index += 2
                    continue
                in_quotes = False
            else:
                field.append(character)
        elif character == '"':
            in_quotes = True
        elif character == ',':
            fields.append(''.join(field))
            field = []
        else:
            field.append(character)

        index += 1

    fields.append(''.join(field))
    return fields
